import"https://unpkg.com/@studio-freight/lenis@1.0.33/dist/lenis.min.js";const s=document.getElementById("section-shift");window.addEventListener("scroll",()=>{const e=s?.getBoundingClientRect();e&&e.top<window.innerHeight/2&&e.bottom>window.innerHeight/2?s?.classList.add("active-bg"):s?.classList.remove("active-bg")});const l=new Lenis({duration:1.2,easing:e=>Math.min(1,1.001-Math.pow(2,-10*e)),orientation:"vertical",gestureOrientation:"vertical",smoothWheel:!0,wheelMultiplier:1,smoothTouch:!1,touchMultiplier:2,infinite:!1});function o(e){l.raf(e),requestAnimationFrame(o)}requestAnimationFrame(o);const a=new IntersectionObserver(e=>{e.forEach(i=>{i.isIntersecting&&i.target.classList.add("active")})},{threshold:.1});document.querySelectorAll(".scroll-reveal").forEach(e=>a.observe(e));const t=document.getElementById("main-header"),r=document.getElementById("mobile-toggle"),c=document.getElementById("mobile-close"),n=document.getElementById("mobile-menu"),d=document.querySelectorAll(".mobile-link");window.addEventListener("scroll",()=>{t&&window.scrollY>50?(t.classList.remove("bg-transparent","py-6"),t.classList.add("bg-brand-off/95","backdrop-blur-sm","shadow-sm","py-4")):t&&(t.classList.add("bg-transparent","py-6"),t.classList.remove("bg-brand-off/95","backdrop-blur-sm","shadow-sm","py-4"))});r?.addEventListener("click",()=>{n?.classList.remove("translate-x-full")});c?.addEventListener("click",()=>{n?.classList.add("translate-x-full")});d.forEach(e=>{e.addEventListener("click",()=>{n?.classList.add("translate-x-full")})});
